    'KiBSPVJmKzkqaTsnCiAgICAgICAgICAgICAgICAnICAgICAgICAgICAgVjMgYXA9e0FwWzMqaV0sQXBbMyppKzFdLEFwWzMqaSsyXX07JwogICAgICAgICAg'; ...
    'ICAgICAgJyAgICAgICAgICAgIFYzIGFxPXtBcVszKmldLEFxWzMqaSsxXSxBcVszKmkrMl19OycKICAgICAgICAgICAgICAgICcgICAgICAgICAgICBWMyBh'; ...
    'Yz17QWNbMyppXSxBY1szKmkrMV0sQWNbMyppKzJdfTsnCiAgICAgICAgICAgICAgICAnJwogICAgICAgICAgICAgICAgJyAgICAgICAgICAgIGRvdWJsZSBz'; ...
    'cD1wb2ludExldmVsKHBMaixjLFIsYXApLTEuMDsnCiAgICAgICAgICAgICAgICAnICAgICAgICAgICAgaWYoc3A8YmVzdCl7IGJlc3Q9c3A7IGJlc3RDb21w'; ...
    'PTE7IGJlc3RPaWQ9aWRzW2ldOyB9JwogICAgICAgICAgICAgICAgJycKICAgICAgICAgICAgICAgICcgICAgICAgICAgICBkb3VibGUgc3E9cG9pbnRMZXZl'; ...
    'bChwUWosYyxSLGFxKS0xLjA7JwogICAgICAgICAgICAgICAgJyAgICAgICAgICAgIGlmKHNxPGJlc3QpeyBiZXN0PXNxOyBiZXN0Q29tcD0yOyBiZXN0T2lk'; ...
