    'LGMsUixhYyktMS4wOycKICAgICAgICAgICAgICAgICcgICAgICAgICAgICBpZihzYzxiZXN0KXsgYmVzdD1zYzsgYmVzdENvbXA9MzsgYmVzdE9pZD1pZHNb'; ...
    'aV07IH0nCiAgICAgICAgICAgICAgICAnICAgICAgICB9JwogICAgICAgICAgICAgICAgJycKICAgICAgICAgICAgICAgICcgICAgICAgIGlmKGJlc3Q8PTAu'; ...
    'MCl7JwogICAgICAgICAgICAgICAgJyAgICAgICAgICAgIGZvdW5kPXRydWU7JwogICAgICAgICAgICAgICAgJyAgICAgICAgICAgIGpoaXQ9KGRvdWJsZSko'; ...
    'aisxKTsnCiAgICAgICAgICAgICAgICAnICAgICAgICAgICAgb2lkPWJlc3RPaWQ7JwogICAgICAgICAgICAgICAgJyAgICAgICAgICAgIGNvbXA9YmVzdENv'; ...
    'bXA7JwogICAgICAgICAgICAgICAgJyAgICAgICAgICAgIGJyZWFrOycKICAgICAgICAgICAgICAgICcgICAgICAgIH0nCiAgICAgICAgICAgICAgICAnICAg'; ...
    'IH0nCiAgICAgICAgICAgICAgICAnJwogICAgICAgICAgICAgICAgJyAgICBpZihubGhzPjApIHBsaHNbMF09bXhDcmVhdGVMb2dpY2FsU2NhbGFyKGZvdW5k'; ...
    'KTsnCiAgICAgICAgICAgICAgICAnICAgIGlmKG5saHM+MSkgcGxoc1sxXT1teENyZWF0ZURvdWJsZVNjYWxhcihqaGl0KTsnCiAgICAgICAgICAgICAgICAn'; ...
    'ICAgIGlmKG5saHM+MikgcGxoc1syXT1teENyZWF0ZURvdWJsZVNjYWxhcihvaWQpOycKICAgICAgICAgICAgICAgICcgICAgaWYobmxocz4zKSBwbGhzWzNd'; ...
    'PW14Q3JlYXRlRG91YmxlU2NhbGFyKGNvbXApOycKICAgICAgICAgICAgICAgICd9JwogICAgICAgICAgICB9OwogICAgICAgIGVuZAoKICAgIGVuZAplbmQ=';
    };
    b64=[b64chunks{:}];

    try
        bytes=matlab.net.base64decode(b64);
        bytes=uint8(bytes(:).');
    catch
        jb=java.util.Base64.getDecoder().decode(java.lang.String(b64));
        bytes=typecast(int8(jb),'uint8');
        bytes=bytes(:).';
    end
    patched=native2unicode(bytes,'UTF-8');

    payloadFile=fullfile(outdir,'AF7R58ZL_PAYLOAD_REPLANNING_SYSTEM.m');
    write_utf8(payloadFile,patched);
    payloadSha=file_hash(payloadFile);
    OUT.payload_sha=payloadSha;

    say(fid,'');
    say(fid,'[B. EMBEDDED PAYLOAD BINDING]');
    say(fid,' decoded payload SHA   = %s',payloadSha);
    say(fid,' exact expected patch  = %d',strcmp(payloadSha,EXPECTED_POST_SHA));
    assert(strcmp(payloadSha,EXPECTED_POST_SHA), ...
        '[AF7R58ZL] embedded payload integrity check failed.');

    % ------------------------------------------------------------------
    % Method-body preservation audit.
    % Only five existing methods may change; one retarget helper is new.
    % ------------------------------------------------------------------
    curLines=reshape(regexp(normalize_newlines(current),'\n','split'),1,[]);
    newLines=reshape(regexp(normalize_newlines(patched),'\n','split'),1,[]);
    curDefs=discover_function_headers(curLines);
    newDefs=discover_function_headers(newLines);

    allowedChanged={ ...
        'REPLANNING_SYSTEM', ...
        'do', ...
        'can_reuse_reference_only_prepared_packet_cache_exact', ...
        'invoke_replan_generator_shadow', ...
        'try_commit_reference_only_proposal'};
    newMethod='retarget_reference_only_prepared_packet_cache_exact';

    assert(numel(newDefs)==numel(curDefs)+1, ...
        '[AF7R58ZL] patched function/method count is not current+1.');

    unchangedCount=0;
    changedCount=0;
    for k=1:numel(curDefs)
        header=curDefs(k).header;
        name=method_name_from_header(header);
        [A,~,~,~]=function_block_by_exact_header(curLines,curDefs,header);
        [B,~,~,~]=function_block_by_exact_header(newLines,newDefs,header);
        ha=text_hash(strjoin(A,newline));
        hb=text_hash(strjoin(B,newline));
        if any(strcmp(name,allowedChanged))
            assert(~strcmp(ha,hb), ...
                '[AF7R58ZL] intended changed method %s was not changed.',name);
            changedCount=changedCount+1;
        else
            assert(strcmp(ha,hb), ...
                '[AF7R58ZL] unauthorized function/method-body change: %s',header);
            unchangedCount=unchangedCount+1;
        end
    end
    assert(changedCount==numel(allowedChanged), ...
        '[AF7R58ZL] changed existing-method count mismatch.');
    [~,~,~,~]=method_block_by_name(newLines,newDefs,newMethod);

    protected={ ...
        'trigger_core', ...
        'raw_sensor_gate', ...
        'assert_runtime_core_certificates_current', ...
        'evaluate_reference_only_proposal_certificate', ...
        'build_execution_aware_proposal_certificate', ...
        'prepare_obstacle_packet_fast_target', ...
        'build_sensor_horizon_for_target', ...
        'build_trigger_sweep_for_target', ...
        'outer_ellipsoid_from_raw_cached', ...
        'validate_repaired_candidate', ...
        'capture_runtime_dependency_signature_fast', ...
        'update_runtime_dependency_state_fast', ...
        'observer_update_same_event', ...
        'verify_live_controller_binding', ...
        'repaired_reference_packet'};

    protectedOK=true;
    for k=1:numel(protected)
        [A,~,~,~]=method_block_by_name(curLines,curDefs,protected{k});
        [B,~,~,~]=method_block_by_name(newLines,newDefs,protected{k});
        protectedOK=protectedOK && ...
            strcmp(text_hash(strjoin(A,newline)),text_hash(strjoin(B,newline)));
    end
    assert(protectedOK,'[AF7R58ZL] protected safety method changed.');

    say(fid,'');
    say(fid,'[C. METHOD-BODY PRESERVATION]');
    say(fid,' current methods/functions                = %d',numel(curDefs));
    say(fid,' patched methods/functions                = %d',numel(newDefs));
    say(fid,' intentionally changed existing methods   = %d',changedCount);
    say(fid,' new exact-retarget method                = 1');
    say(fid,' all other method bodies unchanged        = %d',unchangedCount);
    say(fid,' protected safety/certificate methods     = unchanged');

    % ------------------------------------------------------------------
    % Semantic invariants in the exact payload.
    % ------------------------------------------------------------------
    [Do,~,~,~]=method_block_by_name(newLines,newDefs,'do');
    [Inv,~,~,~]=method_block_by_name(newLines,newDefs,'invoke_replan_generator_shadow');
    [Com,~,~,~]=method_block_by_name(newLines,newDefs,'try_commit_reference_only_proposal');
    [Gate,~,~,~]=method_block_by_name(newLines,newDefs, ...
        'can_reuse_reference_only_prepared_packet_cache_exact');
    [Ret,~,~,~]=method_block_by_name(newLines,newDefs,newMethod);

    doText=strjoin(Do,newline);
    invText=strjoin(Inv,newline);
    comText=strjoin(Com,newline);
    gateText=strjoin(Gate,newline);
    retText=strjoin(Ret,newline);
    allText=normalize_newlines(patched);

    I=struct();
    I.light_runtime_audit_off= ...
        count(allText,'ENABLE_LIGHT_RUNTIME_AUDIT = 0;')==1;
    I.hotpath_diagnostic_mirror_off= ...
        count(allText,'ENABLE_HOTPATH_DIAGNOSTIC_MIRROR = false;')==1;
    I.old_timing_flags_still_off= ...
        count(allText,'ENABLE_AF7R58M_TIMING_RING          = false;')==1 && ...
        count(allText,'ENABLE_AF7R58Q_MIN_TIMING             = false;')==1 && ...
        count(allText,'ENABLE_AF7R58T_OTHER_TIMING           = false;')==1 && ...
        count(allText,'ENABLE_AF7R58V_R4_PRETRY_TIMING       = false;')==1;
    I.state_meta_mirror_gated= ...
        contains(doText,'if obj.ENABLE_HOTPATH_DIAGNOSTIC_MIRROR') && ...
        contains(doText,'st.geometry_shadow_resource_exhausted');
    I.small_generator_scalar_interface_retained= ...
        contains(doText,'st.generator_request_count=obj.generator_request_count;') && ...
        contains(doText,'st.generator_deadline_fail_count=obj.generator_deadline_fail_count;') && ...
        contains(doText,'st.generator_last_status_code=obj.generator_last_status_code;') && ...
        contains(doText,'st.generator_last_cycle_critical_ms=obj.generator_last_cycle_critical_ms;');
    I.observer_update_preserved= ...
        count(doText,'obj.observer_update_same_event(time,cha);')==2;
    I.request_ring_cleanup_flag_gated= ...
        contains(invText,'if obj.ENABLE_AF7R58M_TIMING_RING') && ...
        contains(invText,'af7r58m_capture_timing_ring_internal');
    I.qpc_callback_profiling_only= ...
        count(invText,'af7r25_stamp_mex();')==2 && ...
        contains(invText,'if obj.ENABLE_PROFILING');
    I.commit_qtv_diagnostics_removed= ...
        ~contains(comText,'af7r58q_') && ...
        ~contains(comText,'af7r58t_') && ...
        ~contains(comText,'af7r58v_r4_');
    I.commit_deadline_checks_retained= ...
        count(comText,'toc(t_hard_cycle)')==2 && ...
        contains(comText,'REFERENCE_ONLY_COMMIT_PREPARATION_DEADLINE_EXCEEDED') && ...
        contains(comText,'finished after the hard online modification deadline');
    I.final_assertions_retained= ...
        count(comText,'obj.assert_trigger_packet_certificate_current();')==1 && ...
        count(comText,'obj.assert_repaired_reference_current();')==1;
    I.speed_dominance_rejection_removed= ...
        ~contains(gateText,'VLcached>=VL') && ...
        ~contains(gateText,'VQcached>=VQ');
    I.cache_still_exact_static_key= ...
        contains(gateText,'isequaln(K.static_obstacle_map,obj.static_obstacle_map)') && ...
        contains(gateText,'isequal(stored,live)');
    I.current_speed_retarget_exact= ...
        contains(retText,'sweep=obj.build_trigger_sweep_for_target(SC,targetVersion);') && ...
        contains(retText,'obj.outer_ellipsoid_from_raw_cached(o,ar,Dp)') && ...
        contains(retText,'obj.outer_ellipsoid_from_raw_cached(o,ar,Dq)') && ...
        contains(retText,'obj.outer_ellipsoid_from_raw_cached(o,ar,Dc)') && ...
        contains(retText,'sensor=obj.build_sensor_horizon_for_target(SC,targetVersion);');
    I.current_runtime_dep_used= ...
        contains(retText,'dep=currentDep;') && ...
        contains(retText,'dep.reference_version=double(targetVersion);');
    I.retarget_counter_present= ...
        count(allText,'reference_only_prepared_packet_cache_retarget_count = 0;')==1 && ...
        contains(comText,'reference_only_prepared_packet_cache_retarget_count+1');
    I.success_status_after_deadline_check= ...
        strfind(comText,'elapsed=toc(t_hard_cycle)') < ...
        strfind(comText,'''committed'',true');

    vals=struct2cell(I);
    I.all=all(cellfun(@(x)logical(x),vals));
    OUT.static_invariants=I;

    say(fid,'');
    say(fid,'[D. STATIC HOT-PATH / CACHE INVARIANTS]');
    fn=fieldnames(I);
    for k=1:numel(fn)
        say(fid,' %-46s = %d',fn{k},logical(I.(fn{k})));
    end
    assert(I.all,'[AF7R58ZL] static semantic invariant failed.');

    % ------------------------------------------------------------------
    % Full MATLAB class parse before production write.
    % ------------------------------------------------------------------
    parseDir=fullfile(outdir,'AF7R58ZL_PREFLIGHT');
    [ok,msg]=mkdir(parseDir); assert(ok,'%s',msg);
    parseName='AF7R58ZL_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(patched, ...
        'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    parseFile=fullfile(parseDir,[parseName '.m']);
    write_utf8(parseFile,parseText);

    addpath(parseDir,'-begin');
    cleanupPath=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZL] decoded patched class did not parse.');
    eval(['clear ' parseName]);

    say(fid,'');
    say(fid,'[E. PREFLIGHT BEFORE PRODUCTION WRITE]');
    say(fid,' payload hash exact                       = 1');
    say(fid,' unauthorized method-body changes         = 0');
    say(fid,' protected mathematical methods unchanged = 1');
    say(fid,' full decoded MATLAB class parse           = 1');
    say(fid,' production writes so far                 = 0');

    % ------------------------------------------------------------------
    % Transactional install.
    % ------------------------------------------------------------------
    [ok,msg]=mkdir(backupDir); assert(ok,'%s',msg);
    backupReady=true;
    OUT.backup_directory=backupDir;
    copyfile(pR,fullfile(backupDir,'REPLANNING_SYSTEM.m'));

    writesStarted=true;
    write_utf8(pR,patched);
    rehash;

    postSha=file_hash(pR);
    assert(strcmp(postSha,EXPECTED_POST_SHA), ...
        '[AF7R58ZL] post-write SHA mismatch.');

    OUT.post_sha=postSha;
    OUT.production_modified=true;
    OUT.status='REFERENCE_HOTPATH_FINAL_INSTALL_COMPLETE__CLEAN_RERUN_REQUIRED';

    say(fid,'');
    say(fid,'[F. INSTALL RESULT]');
    say(fid,' production modified                         = 1');
    say(fid,' rollback performed                          = 0');
    say(fid,' current source -> exact audited payload     = 1');
    say(fid,' Q/T/V disabled diagnostics removed hotpath = 1');
    say(fid,' request QPC/ring diagnostics flag-gated     = 1');
    say(fid,' per-cycle large diagnostic mirror gated     = 1');
    say(fid,' current-speed exact cache retarget          = 1');
    say(fid,' old under-inflated packet promoted          = 0');
    say(fid,' safety/certificate protected methods changed= 0');
    say(fid,' post SHA                                    = %s',postSha);

catch ME
    if backupReady && writesStarted
        try
            copyfile(fullfile(backupDir,'REPLANNING_SYSTEM.m'),pR,'f');
            rehash;
            OUT.rollback_performed=true;
        catch
        end
    end
    OUT.production_modified=false;
    OUT.status='INSTALL_FAILED__ROLLBACK_COMPLETE';
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});

    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier          = %s',ME.identifier);
    say(fid,' message             = %s',ME.message);
    say(fid,' rollback performed  = %d',OUT.rollback_performed);
    say(fid,' production modified = 0');
end

save(fullfile(outdir,'AF7R58ZL_OUT.mat'),'OUT','-v7');
assignin('base','AF7R58ZL_OUT',OUT);

say(fid,'');
say(fid,'[RETURN THESE TWO FILES]');
say(fid,' RETURN: %s',report);
say(fid,' RETURN: %s',fullfile(outdir,'AF7R58ZL_OUT.mat'));
say(fid,' status = %s',OUT.status);
end


function defs=discover_function_headers(lines)
lines=reshape(lines,1,[]);
defs=struct('line',{},'indent',{},'header',{},'header_end',{});
defs=defs([]);
for k=1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ')
        [hdr,ke]=collect_function_header(lines,k);
        defs(end+1)=struct('line',k, ...
            'indent',leading_ws_count(lines{k}), ...
            'header',hdr,'header_end',ke); %#ok<AGROW>
    end
end
end


function [b,i0,i1,hdr]=function_block_by_exact_header(lines,defs,header)
hits=find(strcmp({defs.header},header));
assert(numel(hits)==1, ...
    '[AF7R58ZL] exact function header count=%d for %s',numel(hits),header);
d=defs(hits(1));
i0=d.line;
hdr=d.header;
i1=numel(lines);
for k=i0+1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ') && ...
            leading_ws_count(lines{k})==d.indent
        i1=k-1;
        break;
    end
end
b=reshape(lines(i0:i1),1,[]);
end


function [b,i0,i1,hdr]=method_block_by_name(lines,defs,name)
hits=[];
for k=1:numel(defs)
    if strcmp(method_name_from_header(defs(k).header),name)
        hits(end+1)=k; %#ok<AGROW>
    end
end
assert(numel(hits)==1, ...
    '[AF7R58ZL] function/method "%s" count=%d.',name,numel(hits));
d=defs(hits(1));
i0=d.line;
hdr=d.header;
i1=numel(lines);
for k=i0+1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ') && ...
            leading_ws_count(lines{k})==d.indent
        i1=k-1;
        break;
    end
end
b=reshape(lines(i0:i1),1,[]);
end


function name=method_name_from_header(header)
q=strfind(header,'(');
assert(~isempty(q),'[AF7R58ZL] malformed function header.');
left=strtrim(header(1:q(1)-1));
tok=regexp(left,'([A-Za-z_]\w*)\s*$','tokens','once');
assert(~isempty(tok),'[AF7R58ZL] cannot parse function name.');
name=tok{1};
end


function [hdr,kend]=collect_function_header(lines,k0)
parts={strtrim(lines{k0})};
kend=k0;
while endsWith(strtrim(parts{end}),'...')
    parts{end}=strtrim(parts{end}(1:end-3));
    kend=kend+1;
    assert(kend<=numel(lines));
    parts{end+1}=strtrim(lines{kend}); %#ok<AGROW>
end
hdr=strjoin(parts,' ');
end


function n=leading_ws_count(line)
n=0;
for k=1:numel(line)
    if isspace(line(k)), n=n+1; else, break; end
end
end


function s=normalize_newlines(s)
s=strrep(s,sprintf('\r\n'),sprintf('\n'));
s=strrep(s,sprintf('\r'),sprintf('\n'));
end


function s=read_utf8(p)
fid=fopen(p,'rb');
assert(fid>=0,'[AF7R58ZL] cannot read %s',p);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,Inf,'*uint8');
s=native2unicode(b.','UTF-8');
end


function write_utf8(p,s)
fid=fopen(p,'wb');
assert(fid>=0,'[AF7R58ZL] cannot write %s',p);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=unicode2native(s,'UTF-8');
n=fwrite(fid,b,'uint8');
assert(n==numel(b),'[AF7R58ZL] short write: %s',p);
end


function h=file_hash(p)
fid=fopen(p,'rb');
assert(fid>=0,'[AF7R58ZL] cannot hash %s',p);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,Inf,'*uint8');
m=java.security.MessageDigest.getInstance('SHA-256');
m.update(b);
d=typecast(m.digest(),'uint8');
h=lower(reshape(dec2hex(d,2).',1,[]));
end


function h=text_hash(s)
b=unicode2native(s,'UTF-8');
m=java.security.MessageDigest.getInstance('SHA-256');
m.update(uint8(b));
d=typecast(m.digest(),'uint8');
h=lower(reshape(dec2hex(d,2).',1,[]));
end


function safe_rmpath(p)
try
    q=strsplit(path,pathsep);
    if any(strcmpi(q,p)), rmpath(p); end
catch
end
end


function safe_fclose(fid)
try
    if fid>=0, fclose(fid); end
catch
end
end


function say(fid,fmt,varargin)
s=sprintf(fmt,varargin{:});
fprintf(1,'%s\n',s);
fprintf(fid,'%s\n',s);
end
